/* 1. 指针与基本有效性 */
if (qs_input.current_q_bi == NULL || qs_input.target_q_bi == NULL) {
    qs_state.mode = QS_FAULT;
    qs_state.settled = 0U;
    qs_state.commanded_rate_rad_cycle = 0.0;
    qs_state.axis_valid = 0;
    qs_output.mode = QS_FAULT;
    qs_output.settled = 0U;
    qs_output.error_angle_rad = 0.0;
    qs_output.applied_step_rad = 0.0;
    qs_output.commanded_rate_rad_cycle = 0.0;
    qs_output.braking_rate_rad_cycle = 0.0;
    qs_output.reversal_reset = 0;
    qs_output.slew_axis = (adcs_vec3_t){0, 0, 0};
    qs_output.command_q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}
/* 2. 配置有效性 */
if (!isfinite(qs_config.max_rate_rad_cycle) || !isfinite(qs_config.max_accel_rad_cycle2) ||
    !isfinite(qs_config.settle_angle_rad) || !isfinite(qs_config.settle_rate_rad_cycle) ||
    qs_config.max_rate_rad_cycle <= 0.0 || qs_config.max_rate_rad_cycle > ADCS_PI ||
    qs_config.max_accel_rad_cycle2 <= 0.0 ||
    qs_config.settle_rate_rad_cycle < 0.0 ||
    qs_config.settle_rate_rad_cycle > qs_config.max_rate_rad_cycle ||
    qs_config.settle_angle_rad < 0.0 ||
    qs_config.settle_angle_rad > qs_config.max_rate_rad_cycle ||
    qs_config.settle_cycles < 1U || qs_config.settle_cycles > 20U) {
    qs_state.mode = QS_FAULT;
    qs_state.settled = 0U;
    qs_state.commanded_rate_rad_cycle = 0.0;
    qs_state.axis_valid = 0;
    qs_output.mode = QS_FAULT;
    qs_output.settled = 0U;
    qs_output.error_angle_rad = 0.0;
    qs_output.applied_step_rad = 0.0;
    qs_output.commanded_rate_rad_cycle = 0.0;
    qs_output.braking_rate_rad_cycle = 0.0;
    qs_output.reversal_reset = 0;
    qs_output.slew_axis = (adcs_vec3_t){0, 0, 0};
    qs_output.command_q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}
/* 3. 四元数有限性 */
if (!isfinite(qs_input.current_q_bi->w) || !isfinite(qs_input.current_q_bi->x) ||
    !isfinite(qs_input.current_q_bi->y) || !isfinite(qs_input.current_q_bi->z) ||
    !isfinite(qs_input.target_q_bi->w) || !isfinite(qs_input.target_q_bi->x) ||
    !isfinite(qs_input.target_q_bi->y) || !isfinite(qs_input.target_q_bi->z)) {
    qs_state.mode = QS_FAULT;
    qs_state.settled = 0U;
    qs_state.commanded_rate_rad_cycle = 0.0;
    qs_state.axis_valid = 0;
    qs_output.mode = QS_FAULT;
    qs_output.settled = 0U;
    qs_output.error_angle_rad = 0.0;
    qs_output.applied_step_rad = 0.0;
    qs_output.commanded_rate_rad_cycle = 0.0;
    qs_output.braking_rate_rad_cycle = 0.0;
    qs_output.reversal_reset = 0;
    qs_output.slew_axis = (adcs_vec3_t){0, 0, 0};
    qs_output.command_q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}

/* 4. 归一化 current、target */
adcs_quat_t cur_n, tgt_n;
if (adcs_quat_normalize(qs_input.current_q_bi, &cur_n) != ADCS_OK ||
    adcs_quat_normalize(qs_input.target_q_bi, &tgt_n) != ADCS_OK) {
    qs_state.mode = QS_FAULT;
    qs_state.settled = 0U;
    qs_state.commanded_rate_rad_cycle = 0.0;
    qs_state.axis_valid = 0;
    qs_output.mode = QS_FAULT;
    qs_output.settled = 0U;
    qs_output.error_angle_rad = 0.0;
    qs_output.applied_step_rad = 0.0;
    qs_output.commanded_rate_rad_cycle = 0.0;
    qs_output.braking_rate_rad_cycle = 0.0;
    qs_output.reversal_reset = 0;
    qs_output.slew_axis = (adcs_vec3_t){0, 0, 0};
    qs_output.command_q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}

/* 5. Disable -> HOLD 且清历史 */
if (!qs_input.enable) {
    qs_state.mode = QS_HOLD;
    qs_state.settled = 0U;
    qs_state.commanded_rate_rad_cycle = 0.0;
    qs_state.axis_valid = 0;
    qs_state.previous_axis = (adcs_vec3_t){0, 0, 0};
    qs_output.mode = QS_HOLD;
    qs_output.settled = 0U;
    qs_output.error_angle_rad = 0.0;
    qs_output.applied_step_rad = 0.0;
    qs_output.commanded_rate_rad_cycle = 0.0;
    qs_output.braking_rate_rad_cycle = 0.0;
    qs_output.reversal_reset = 0;
    qs_output.slew_axis = (adcs_vec3_t){0, 0, 0};
    qs_output.command_q_bi = cur_n;
    return;
}

/* 6. relative = target * conj(current)，取最短符号 */
adcs_quat_t cur_c = adcs_quat_conjugate(&cur_n);
adcs_quat_t rel = adcs_quat_multiply(&tgt_n, &cur_c);
if (rel.w < 0.0) {
    rel.w = -rel.w;
    rel.x = -rel.x;
    rel.y = -rel.y;
    rel.z = -rel.z;
}

/* 7. 主角与旋转轴 */
double rw = ADCS_CLAMP(rel.w, -1.0, 1.0);
double angle = 2.0 * acos(rw);
adcs_vec3_t axis;
double axis_norm = sqrt(rel.x * rel.x + rel.y * rel.y + rel.z * rel.z);
if (axis_norm > ADCS_EPS_NORM) {
    axis = (adcs_vec3_t){rel.x / axis_norm, rel.y / axis_norm, rel.z / axis_norm};
} else {
    axis = (adcs_vec3_t){0, 0, 0};
}

/* 8. 刹车包络与目标速率 */
double braking = sqrt(2.0 * qs_config.max_accel_rad_cycle2 * angle);
double target_rate = qs_config.max_rate_rad_cycle;
if (braking < target_rate) {
    target_rate = braking;
}

/* 9. 反向复位：新轴与上一非零轴负点积时先清 rate */
int reversal_reset = 0;
if (qs_state.axis_valid) {
    double d = adcs_vec3_dot(&axis, &qs_state.previous_axis);
    if (d < 0.0) {
        qs_state.commanded_rate_rad_cycle = 0.0;
        reversal_reset = 1;
    }
}

/* 10. 限幅向 target_rate 移动，至多 max_accel */
double rate_prev = qs_state.commanded_rate_rad_cycle;
double rate = rate_prev;
if (rate < target_rate) {
    rate += qs_config.max_accel_rad_cycle2;
    if (rate > target_rate) {
        rate = target_rate;
    }
} else if (rate > target_rate) {
    rate -= qs_config.max_accel_rad_cycle2;
    if (rate < target_rate) {
        rate = target_rate;
    }
}
qs_state.commanded_rate_rad_cycle = rate;

/* 11. 模式判定：上升 ACCEL，等于速率上限 CRUISE，下降 DECEL */
if (rate > rate_prev) {
    qs_state.mode = QS_ACCEL;
} else if (rate < rate_prev) {
    qs_state.mode = QS_DECEL;
} else if (rate >= qs_config.max_rate_rad_cycle - FLT64_ZERO) {
    qs_state.mode = QS_CRUISE;
} else {
    qs_state.mode = QS_CRUISE;
}

/* 12. 记录上一非零轴 */
if (axis_norm > ADCS_EPS_NORM) {
    qs_state.previous_axis = axis;
    qs_state.axis_valid = 1;
}

/* 13. settle 判定 */
if (angle <= qs_config.settle_angle_rad && rate <= qs_config.settle_rate_rad_cycle) {
    qs_state.settled += 1U;
    if (qs_state.settled >= qs_config.settle_cycles) {
        qs_state.mode = QS_HOLD;
        qs_state.settled = 0U;
    } else {
        qs_state.mode = QS_SETTLE;
    }
} else {
    qs_state.settled = 0U;
}

/* 14. 施加 min(rate, angle) */
double applied = rate;
if (applied > angle) {
    applied = angle;
}

/* 15. 输出 command quaternion */
adcs_quat_t cmd_q;
if (applied > 0.0 && axis_norm > ADCS_EPS_NORM) {
    double half = 0.5 * applied;
    double s = sin(half);
    adcs_quat_t dq = {cos(half), axis.x * s, axis.y * s, axis.z * s};
    adcs_quat_t next = adcs_quat_multiply(&dq, &cur_n);
    (void)adcs_quat_normalize(&next, &cmd_q);
} else {
    cmd_q = cur_n;
}

qs_output.mode = qs_state.mode;
qs_output.settled = qs_state.settled;
qs_output.error_angle_rad = angle;
qs_output.applied_step_rad = applied;
qs_output.commanded_rate_rad_cycle = rate;
qs_output.braking_rate_rad_cycle = braking;
qs_output.reversal_reset = reversal_reset;
qs_output.slew_axis = axis;
qs_output.command_q_bi = cmd_q;

