    valid = 0;
} else if ((qs_config.settle_rate_rad_cycle < 0.0) ||
           (qs_config.settle_rate_rad_cycle > qs_config.max_rate_rad_cycle)) {
    valid = 0;
} else if ((qs_config.settle_angle_rad < 0.0) ||
           (qs_config.settle_angle_rad > qs_config.max_rate_rad_cycle)) {
    valid = 0;
} else if ((qs_config.settle_cycles < 1U) || (qs_config.settle_cycles > 20U)) {
    valid = 0;
} else {
    cw = qs_input.current_q_bi->w; cx = qs_input.current_q_bi->x;
    cy = qs_input.current_q_bi->y; cz = qs_input.current_q_bi->z;
    tw = qs_input.target_q_bi->w; tx = qs_input.target_q_bi->x;
    ty = qs_input.target_q_bi->y; tz = qs_input.target_q_bi->z;
    if ((!isfinite(cw)) || (!isfinite(cx)) || (!isfinite(cy)) || (!isfinite(cz)) ||
        (!isfinite(tw)) || (!isfinite(tx)) || (!isfinite(ty)) || (!isfinite(tz))) {
        valid = 0;
    } else {
        cn = sqrt(cw*cw + cx*cx + cy*cy + cz*cz);
        tn = sqrt(tw*tw + tx*tx + ty*ty + tz*tz);
        if ((cn <= ADCS_EPS_QUAT) || (tn <= ADCS_EPS_QUAT)) {
            valid = 0;
        } else {
            valid = 1;
        }
    }
}

if (!valid) {
    qs_state.mode = QS_FAULT;
    qs_state.settled = 0U;
    qs_state.commanded_rate_rad_cycle = 0.0;
    qs_state.axis_valid = 0;
    qs_state.previous_axis = (adcs_vec3_t){0, 0, 0};
    qs_output.mode = QS_FAULT;
    qs_output.settled = 0U;
    qs_output.error_angle_rad = 0.0;
    qs_output.applied_step_rad = 0.0;
    qs_output.commanded_rate_rad_cycle = 0.0;
    qs_output.braking_rate_rad_cycle = 0.0;
    qs_output.reversal_reset = 0;
    qs_output.slew_axis = (adcs_vec3_t){0, 0, 0};
    qs_output.command_q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}

/* Disable：HOLD 并清空 profile 历史 */
if (!qs_input.enable) {
    qs_state.mode = QS_HOLD;
    qs_state.settled = 0U;
    qs_state.commanded_rate_rad_cycle = 0.0;
    qs_state.axis_valid = 0;
    qs_state.previous_axis = (adcs_vec3_t){0, 0, 0};
    qs_output.mode = QS_HOLD;
    qs_output.settled = 0U;
    qs_output.error_angle_rad = 0.0;
    qs_output.applied_step_rad = 0.0;
    qs_output.commanded_rate_rad_cycle = 0.0;
    qs_output.braking_rate_rad_cycle = 0.0;
    qs_output.reversal_reset = 0;
    qs_output.slew_axis = (adcs_vec3_t){0, 0, 0};
    qs_output.command_q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}

/* 2. 归一化 current / target */
(void)adcs_quat_normalize(qs_input.current_q_bi, &cur);
(void)adcs_quat_normalize(qs_input.target_q_bi, &tgt);

/* 3. 相对四元数 shortest-sign */
rel = adcs_quat_multiply(&tgt, &(adcs_quat_t){cur.w, -cur.x, -cur.y, -cur.z});
if (rel.w < 0.0) {
    rel.w = -rel.w; rel.x = -rel.x; rel.y = -rel.y; rel.z = -rel.z;
}
if (rel.w > 1.0) rel.w = 1.0;
if (rel.w < -1.0) rel.w = -1.0;

/* 4. 主轴角与轴 */
angle = 2.0 * acos(rel.w);
if (angle > ADCS_PI) angle = ADCS_PI;
if (angle < 0.0) angle = 0.0;

sin_half = sqrt(rel.x*rel.x + rel.y*rel.y + rel.z*rel.z);
if ((sin_half <= ADCS_EPS_NORM) || (angle <= ADCS_EPS_NORM)) {
    axis = (adcs_vec3_t){0, 0, 0};
} else {
    axis = (adcs_vec3_t){rel.x / sin_half, rel.y / sin_half, rel.z / sin_half};
}
axis_norm = adcs_vec3_norm(&axis);

/* 5. 刹车包络 */
envelope = sqrt(2.0 * qs_config.max_accel_rad_cycle2 * angle);

/* 6. 速率一步更新 */
target_rate = qs_config.max_rate_rad_cycle;
if (envelope < target_rate) target_rate = envelope;

if (qs_state.commanded_rate_rad_cycle < target_rate) {
    qs_state.commanded_rate_rad_cycle += qs_config.max_accel_rad_cycle2;
    if (qs_state.commanded_rate_rad_cycle > target_rate)
        qs_state.commanded_rate_rad_cycle = target_rate;
    qs_state.mode = QS_ACCEL;
} else if (qs_state.commanded_rate_rad_cycle > target_rate) {
    qs_state.commanded_rate_rad_cycle -= qs_config.max_accel_rad_cycle2;
    if (qs_state.commanded_rate_rad_cycle < target_rate)
        qs_state.commanded_rate_rad_cycle = target_rate;
    qs_state.mode = QS_DECEL;
} else {
    qs_state.mode = QS_CRUISE;
}

if (qs_state.commanded_rate_rad_cycle < 0.0)
    qs_state.commanded_rate_rad_cycle = 0.0;

/* 7. 轴向反转重置 */
if (axis_norm > ADCS_EPS_NORM) {
    if (qs_state.axis_valid) {
        dot_old = adcs_vec3_dot(&axis, &qs_state.previous_axis);
        if (dot_old < 0.0) {
            qs_state.commanded_rate_rad_cycle = 0.0;
            qs_state.mode = QS_ACCEL;
            qs_output.reversal_reset = 1;
        }
    }
    qs_state.previous_axis = axis;
    qs_state.axis_valid = 1;
}

/* 8. 应用步长 min(rate, angle) */
step = qs_state.commanded_rate_rad_cycle;
if (step > angle) step = angle;
if (step < 0.0) step = 0.0;

/* 9. 沉降计数 */
if ((angle <= qs_config.settle_angle_rad) &&
    (qs_state.commanded_rate_rad_cycle <= qs_config.settle_rate_rad_cycle)) {
    if (qs_state.settled < qs_config.settle_cycles)
        qs_state.settled += 1U;
    if (qs_state.settled >= qs_config.settle_cycles) {
        qs_state.mode = QS_HOLD;
    } else {
        qs_state.mode = QS_SETTLE;
    }
} else {
    qs_state.settled = 0U;
}

/* 10. 命令四元数 */
if ((step > ADCS_EPS_NORM) && (axis_norm > ADCS_EPS_NORM)) {
    double half = 0.5 * step;
    double s = sin(half);
    adcs_quat_t dq = {cos(half), s * axis.x, s * axis.y, s * axis.z};
    cmd = adcs_quat_multiply(&dq, &cur);
    (void)adcs_quat_normalize(&cmd, &cmd);
} else {
    cmd = cur;
}

/* 11. 输出 */
qs_output.mode = qs_state.mode;
qs_output.settled = qs_state.settled;
qs_output.error_angle_rad = angle;
qs_output.applied_step_rad = step;
qs_output.commanded_rate_rad_cycle = qs_state.commanded_rate_rad_cycle;
qs_output.braking_rate_rad_cycle = envelope;
qs_output.slew_axis = axis;
qs_output.command_q_bi = cmd;
